class Solution { public:int takeCharacters(string s,int k){int total[3]={};for(char character:s)++total[character-'a'];for(int count:total)if(count<k)return -1;int window[3]={},left=0,maximum=0;for(int right=0;right<(int)s.size();++right){int index=s[right]-'a';++window[index];while(window[index]>total[index]-k)--window[s[left++]-'a'];maximum=max(maximum,right-left+1);}return s.size()-maximum;} };
